#!/usr/bin/env bash

#
# Create a Cloudy Pad release - fully automated and idempotent.
#
# All work happens on branch release-X.Y.Z and tag vX.Y.Z:
#   1. Stamp versions (package.json, cloudypad.sh, install.sh, flake.nix) and
#      CHANGELOG.md (generated by git-cliff) in a single commit
#   2. Tag vX.Y.Z, which triggers the Release workflow (container images)
#   3. Wait for the Release workflow to succeed
#   4. Verify published images and flake hash
#   5. Publish GitHub release
#   6. Open PR release-X.Y.Z -> master
#
# The script NEVER writes to master. Merging the PR (with a merge commit) is
# the final, manual action and makes the release live for install.sh users.
#
# Safe to re-run at any point: progress is derived from remote state and
# completed steps are skipped.
#
# Usage:
#   release-create.sh [VERSION]          Create or resume a release
#   release-create.sh --abort [VERSION]  Undo a release whose PR is not merged
#
# VERSION (X.Y.Z) defaults to the release in progress (open release PR or
# release branch), or to git-cliff bumped version if no release is in progress.
#
# Environment:
#   GITHUB_TOKEN                 Required. Repo contents + pull requests write.
#   CLOUDYPAD_RELEASE_DRY_RUN    If "true", stamp and commit on local release
#                                branch only, push nothing.
#

set -euo pipefail
shopt -s inherit_errexit

REMOTE="origin"
BASE_BRANCH="master"
RELEASE_WORKFLOW="release.yml"
export GH_REPO="${CLOUDYPAD_RELEASE_GH_REPO:-PierreBeucher/cloudypad}"
CORE_IMAGE="${CLOUDYPAD_BUILD_CORE_IMAGE_REGISTRY:-ghcr.io/pierrebeucher/cloudypad}"
SUNSHINE_IMAGE="${CLOUDYPAD_BUILD_SUNSHINE_IMAGE_REGISTRY:-ghcr.io/pierrebeucher/cloudypad/sunshine}"
CI_WATCH_TIMEOUT="${CLOUDYPAD_RELEASE_CI_WATCH_TIMEOUT:-3600}"
CI_RUN_REGISTER_TIMEOUT=300
DRY_RUN="${CLOUDYPAD_RELEASE_DRY_RUN:-false}"
# Release candidate: X.Y.Z-rc. Prerelease versions are published as GitHub
# prereleases (not latest) and are not release boundaries for git-cliff.
VERSION_REGEX='^[0-9]+\.[0-9]+\.[0-9]+(-rc)?$'
RC_REGEX='-rc$'

# Set once version is resolved
V=""
TAG=""
BRANCH=""
STAMP_SUBJECT=""
WORK_DIR=""

# Set by steps
STAMP_SHA=""
RELEASE_RUN_URL=""
RELEASE_URL=""

#
# Utils
#

log() {
  echo "[release] $*" >&2
}

fail() {
  echo "[release] ERROR: $*" >&2
  exit 1
}

# Print header comment of this script
usage() {
  awk 'NR > 2 && /^#/ { sub(/^# ?/, ""); print; next } NR > 2 { exit }' "$0"
}

is_dry_run() {
  [ "$DRY_RUN" = "true" ]
}

# True if version $1 is strictly greater than version $2
version_gt() {
  [ "$1" != "$2" ] && [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V | tail -n1)" = "$1" ]
}

# Sorted release tags (vX.Y.Z only). Extra args are passed to git tag (eg. --merged REF)
release_tags() {
  git tag -l "$@" 'v*' | { grep -E '^v[0-9]+\.[0-9]+\.[0-9]+$' || true; } | sort -V
}

# sha256 flat file hash in Nix base32 format, as expected by fetchurl in flake.nix
nix_flat_hash() {
  nix-hash --type sha256 --flat --base32 "$1"
}

remote_branch_exists() {
  git ls-remote --exit-code --heads "$REMOTE" "refs/heads/$1" >/dev/null
}

# Commit SHA pointed by remote tag $1, empty if tag does not exist
remote_tag_commit() {
  git ls-remote "$REMOTE" "refs/tags/$1" "refs/tags/$1^{}" \
    | awk '$2 ~ /\^\{\}$/ { peeled=$1 } NR==1 { first=$1 } END { print (peeled != "" ? peeled : first) }'
}

# Field $2 of the first PR release-$V -> master in state $1 (open|merged), empty if none
release_pr_field() {
  gh pr list --head "$BRANCH" --base "$BASE_BRANCH" --state "$1" --json "$2" --jq ".[0].$2 // empty"
}

# Replace the single line matching ERE $2 in file $1 by $3. Fail unless exactly one line matches.
replace_once() {
  local file=$1 pattern=$2 replacement=$3 count
  count=$(grep -cE "$pattern" "$file" || true)
  [ "$count" = "1" ] || fail "$file: expected exactly 1 line matching /$pattern/, found $count"
  sed -i -E "s|$pattern|$replacement|" "$file"
}

# Print CHANGELOG.md section for $V at git ref $1 (from "## [$V]" heading to next "## [" heading)
changelog_section() {
  git show "$1:CHANGELOG.md" | awk -v heading="## [$V]" '
    index($0, heading) == 1 { found=1 }
    found && !done && /^## \[/ && index($0, heading) != 1 { done=1 }
    found && !done { print }
  '
}

#
# Version resolution
#

# Versions of releases in progress: open release PRs and remote release branches
# with a version greater than latest release merged in master
in_progress_versions() {
  local base v
  base=$(release_tags --merged "$REMOTE/$BASE_BRANCH" | tail -n1)
  base=${base#v}

  {
    gh pr list --base "$BASE_BRANCH" --state open --json headRefName --jq '.[].headRefName'
    git ls-remote --heads "$REMOTE" 'refs/heads/release-*' | awk '{ sub("^refs/heads/", "", $2); print $2 }'
  } | { grep -E '^release-[0-9]+\.[0-9]+\.[0-9]+(-rc)?$' || true; } | sed 's/^release-//' | sort -uV \
    | while read -r v; do
        if [ -z "$base" ] || version_gt "$v" "$base"; then
          echo "$v"
        fi
      done
}

# Resolve release version from requested version $1 (may be empty) and mode $2 (release|abort)
resolve_version() {
  local requested=$1 mode=$2 in_progress count bumped

  in_progress=$(in_progress_versions)
  count=$(grep -c . <<<"$in_progress" || true)

  if [ -n "$requested" ]; then
    if [ "$mode" = "release" ] && [ "$count" -gt 0 ] && [ "$in_progress" != "$requested" ]; then
      fail "release(s) already in progress: $(echo $in_progress). Finish or abort before releasing $requested."
    fi
    echo "$requested"
    return
  fi

  if [ "$count" -gt 1 ]; then
    fail "multiple releases in progress: $(echo $in_progress). Pass VERSION explicitly."
  fi

  if [ "$count" -eq 1 ]; then
    log "Release in progress found: $in_progress"
    echo "$in_progress"
    return
  fi

  if [ "$mode" = "abort" ]; then
    fail "no release in progress to abort. Pass VERSION explicitly."
  fi

  # git-cliff computes next version from commits since latest tag reachable from HEAD
  git checkout --quiet --detach "$REMOTE/$BASE_BRANCH"
  bumped=$(git cliff --config cliff.toml --bumped-version)
  bumped=${bumped#v}
  log "No release in progress, using git-cliff bumped version: $bumped"
  echo "$bumped"
}

#
# Preflight
#

preflight_common() {
  local bin
  for bin in git gh jq git-cliff nix-hash curl docker timeout awk sed sort; do
    command -v "$bin" >/dev/null || fail "missing required binary: $bin"
  done

  [ -n "${GITHUB_TOKEN:-}" ] || fail "GITHUB_TOKEN must be set (repo contents + pull requests write), eg. via 'source <(novops load -e release)'"
  gh api "repos/$GH_REPO" --jq .full_name >/dev/null || fail "cannot access GitHub repository $GH_REPO with current GITHUB_TOKEN"

  [ -z "$(git status --porcelain --untracked-files=no)" ] || fail "working tree is not clean"
}

# Checks only applicable to a fresh release (no remote release branch nor tag)
preflight_fresh() {
  local latest
  latest=$(release_tags | tail -n1)

  if [ -n "$latest" ]; then
    version_gt "$V" "${latest#v}" || fail "version $V must be greater than latest release $latest"

    git merge-base --is-ancestor "$latest" "$REMOTE/$BASE_BRANCH" \
      || fail "previous release tag $latest is not reachable from $BASE_BRANCH: its release PR is not merged (or was not merged with a merge commit)"
  fi
}

#
# Step 1 - Stamp
#

# Return 1 and log details if version files and CHANGELOG at git ref $1 are not consistently stamped for $V
check_stamp() {
  local ref=$1 ok=0 pkg_v sh_v install_ref flake_v flake_hash actual_hash changelog_count

  pkg_v=$(git show "$ref:package.json" | jq -r .version)
  sh_v=$(git show "$ref:cloudypad.sh" | sed -n -E 's/^CLOUDYPAD_VERSION=(.*)$/\1/p')
  install_ref=$(git show "$ref:install.sh" | sed -n -E 's/^DEFAULT_CLOUDYPAD_SCRIPT_REF=(.*)$/\1/p')
  flake_v=$(git show "$ref:flake.nix" | sed -n -E 's/^ *cloudypadVersion = "(.*)";$/\1/p')
  flake_hash=$(git show "$ref:flake.nix" | sed -n -E 's/^ *hash = "sha256:(.*)";$/\1/p')

  git show "$ref:cloudypad.sh" > "$WORK_DIR/cloudypad.sh.stamped"
  actual_hash=$(nix_flat_hash "$WORK_DIR/cloudypad.sh.stamped")

  changelog_count=$(git show "$ref:CHANGELOG.md" | grep -cF "## [$V]" || true)

  [ "$pkg_v" = "$V" ]          || { log "package.json version '$pkg_v' != '$V'"; ok=1; }
  [ "$sh_v" = "$V" ]           || { log "cloudypad.sh CLOUDYPAD_VERSION '$sh_v' != '$V'"; ok=1; }
  [ "$install_ref" = "$TAG" ]  || { log "install.sh DEFAULT_CLOUDYPAD_SCRIPT_REF '$install_ref' != '$TAG'"; ok=1; }
  [ "$flake_v" = "$V" ]        || { log "flake.nix cloudypadVersion '$flake_v' != '$V'"; ok=1; }
  [ "$flake_hash" = "$actual_hash" ] || { log "flake.nix hash '$flake_hash' != cloudypad.sh hash '$actual_hash'"; ok=1; }
  [ "$changelog_count" -ge 1 ] || { log "CHANGELOG.md has no '## [$V]' section"; ok=1; }

  return $ok
}

# Insert changelog section file $1 below "# Changelog" title of CHANGELOG.md
insert_changelog_section() {
  [ "$(head -n1 CHANGELOG.md)" = "# Changelog" ] || fail "CHANGELOG.md first line must be '# Changelog'"

  {
    echo "# Changelog"
    echo
    printf '%s\n' "$(cat "$1")"
    echo
    tail -n +2 CHANGELOG.md | sed '/./,$!d'
  } > "$WORK_DIR/CHANGELOG.md.new"

  mv "$WORK_DIR/CHANGELOG.md.new" CHANGELOG.md
}

step_stamp() {
  local head stamp_count section="$WORK_DIR/changelog-section.md" changelog_count cloudypad_sh_hash

  if remote_branch_exists "$BRANCH"; then
    head=$(git rev-parse "$REMOTE/$BRANCH")

    if [ "$(git log -1 --format=%s "$head")" = "$STAMP_SUBJECT" ]; then
      check_stamp "$head" || fail "$REMOTE/$BRANCH stamp commit $head is inconsistent (see above)"
      log "Step 1 - Stamp: done ($BRANCH at $head)"
      STAMP_SHA=$head
      return
    fi

    stamp_count=$(git log --format=%s "$REMOTE/$BASE_BRANCH..$head" | grep -cxF "$STAMP_SUBJECT" || true)
    [ "$stamp_count" = "0" ] || fail "$REMOTE/$BRANCH has commits on top of stamp commit '$STAMP_SUBJECT'"

    log "Step 1 - Stamp: reusing existing branch $BRANCH"
    git checkout --quiet -B "$BRANCH" "$REMOTE/$BRANCH"
  else
    log "Step 1 - Stamp: creating branch $BRANCH from $REMOTE/$BASE_BRANCH"
    git checkout --quiet -B "$BRANCH" "$REMOTE/$BASE_BRANCH"
  fi

  changelog_count=$(grep -cF "## [$V]" CHANGELOG.md || true)
  if [ "$changelog_count" -ge 1 ]; then
    log "CHANGELOG.md already contains section for $V, keeping it"
  else
    git cliff --config cliff.toml --unreleased --tag "$TAG" > "$section"
    [ "$(grep -cE '^\* ' "$section" || true)" -ge 1 ] \
      || fail "no user-facing change (feat, fix, perf) since previous release: nothing to release"
    insert_changelog_section "$section"
  fi

  replace_once package.json '^  "version": "[^"]*",$' "  \"version\": \"$V\","
  replace_once cloudypad.sh '^CLOUDYPAD_VERSION=.*$' "CLOUDYPAD_VERSION=$V"
  replace_once install.sh '^DEFAULT_CLOUDYPAD_SCRIPT_REF=.*$' "DEFAULT_CLOUDYPAD_SCRIPT_REF=$TAG"
  replace_once flake.nix '^( *)cloudypadVersion = "[^"]*";$' "\\1cloudypadVersion = \"$V\";"

  # Hash computed after cloudypad.sh is stamped: must match the exact committed bytes
  cloudypad_sh_hash=$(nix_flat_hash cloudypad.sh)
  replace_once flake.nix '^( *)hash = "sha256:[^"]*";$' "\\1hash = \"sha256:$cloudypad_sh_hash\";"

  git add package.json cloudypad.sh install.sh flake.nix CHANGELOG.md
  git commit --quiet -m "$STAMP_SUBJECT"

  check_stamp HEAD || fail "stamp commit is inconsistent (see above). Local commit only, nothing pushed."

  if is_dry_run; then
    git --no-pager show --stat HEAD >&2
    log "Dry run: changelog section:"
    changelog_section HEAD >&2
    log "Dry run: stamp committed on local branch $BRANCH only, nothing pushed."
    exit 0
  fi

  git push --quiet --set-upstream "$REMOTE" "$BRANCH"
  STAMP_SHA=$(git rev-parse HEAD)
  log "Step 1 - Stamp: pushed $BRANCH at $STAMP_SHA"
}

#
# Step 2 - Tag
#

step_tag() {
  local remote_commit
  remote_commit=$(remote_tag_commit "$TAG")

  if [ -n "$remote_commit" ]; then
    [ "$remote_commit" = "$STAMP_SHA" ] || fail "remote tag $TAG points to $remote_commit, expected stamp commit $STAMP_SHA"
    log "Step 2 - Tag: done ($TAG)"
    return
  fi

  # Leftover local tag from an interrupted run: keep it only if it points to stamp commit
  if git rev-parse -q --verify "refs/tags/$TAG" >/dev/null \
     && [ "$(git rev-parse "refs/tags/$TAG^{commit}")" != "$STAMP_SHA" ]; then
    log "Deleting local tag $TAG not pointing to stamp commit"
    git tag -d "$TAG" >/dev/null
  fi

  if ! git rev-parse -q --verify "refs/tags/$TAG" >/dev/null; then
    git tag -a "$TAG" -m "Release $TAG" "$STAMP_SHA"
  fi

  git push --quiet "$REMOTE" "refs/tags/$TAG"
  log "Step 2 - Tag: pushed $TAG"
}

#
# Step 3 - Watch Release CI
#

step_ci() {
  local run_json="" waited=0 run_id status conclusion rc

  while :; do
    run_json=$(gh run list --workflow "$RELEASE_WORKFLOW" --event push --commit "$STAMP_SHA" --limit 20 \
      --json databaseId,status,conclusion,url,createdAt --jq 'sort_by(.createdAt) | last // empty')
    [ -n "$run_json" ] && break

    [ "$waited" -lt "$CI_RUN_REGISTER_TIMEOUT" ] \
      || fail "no $RELEASE_WORKFLOW run found for $TAG ($STAMP_SHA) after ${waited}s"

    log "Step 3 - CI: waiting for $RELEASE_WORKFLOW run to be registered for $TAG..."
    sleep 10
    waited=$((waited + 10))
  done

  run_id=$(jq -r .databaseId <<<"$run_json")
  status=$(jq -r .status <<<"$run_json")
  RELEASE_RUN_URL=$(jq -r .url <<<"$run_json")

  if [ "$status" != "completed" ]; then
    log "Step 3 - CI: watching $RELEASE_RUN_URL (timeout ${CI_WATCH_TIMEOUT}s)"
    rc=0
    timeout "$CI_WATCH_TIMEOUT" gh run watch "$run_id" --exit-status --interval 30 >&2 || rc=$?
    [ "$rc" != "124" ] || fail "timed out watching $RELEASE_RUN_URL. Re-run this script to resume watching."
  fi

  conclusion=$(gh run view "$run_id" --json conclusion --jq .conclusion)
  if [ "$conclusion" != "success" ]; then
    fail "Release CI run concluded '$conclusion': $RELEASE_RUN_URL
  Rerun failed jobs with: gh run rerun $run_id --failed
  then re-run this script to resume. For a code problem, abort with: $0 --abort $V"
  fi

  log "Step 3 - CI: done ($RELEASE_RUN_URL)"
}

#
# Step 4 - Verify
#

step_verify() {
  local manifest expected_hash served_hash image_version

  manifest=$(docker manifest inspect "$CORE_IMAGE:$V") || fail "image $CORE_IMAGE:$V not found"
  jq -e '[.manifests[]?.platform | "\(.os)/\(.architecture)"] | any(. == "linux/amd64") and any(. == "linux/arm64")' \
    <<<"$manifest" >/dev/null || fail "image $CORE_IMAGE:$V does not provide both linux/amd64 and linux/arm64"

  docker manifest inspect "$SUNSHINE_IMAGE:$V" >/dev/null || fail "image $SUNSHINE_IMAGE:$V not found"

  # Download the file actually served for the tag: a local Nix build would be satisfied
  # by any store path with the same hash without fetching from GitHub
  curl -fsSL "https://raw.githubusercontent.com/$GH_REPO/$TAG/cloudypad.sh" -o "$WORK_DIR/cloudypad.sh.served" \
    || fail "cannot download cloudypad.sh for $TAG"
  served_hash=$(nix_flat_hash "$WORK_DIR/cloudypad.sh.served")
  expected_hash=$(git show "$STAMP_SHA:flake.nix" | sed -n -E 's/^ *hash = "sha256:(.*)";$/\1/p')
  [ "$served_hash" = "$expected_hash" ] \
    || fail "flake.nix hash '$expected_hash' does not match cloudypad.sh served for $TAG ('$served_hash')"

  image_version=$(docker run --rm --pull always "$CORE_IMAGE:$V" --version) || fail "cannot run image $CORE_IMAGE:$V"
  image_version=$(tr -d '[:space:]' <<<"$image_version")
  [ "$image_version" = "$V" ] || fail "image $CORE_IMAGE:$V reports version '$image_version', expected '$V'"

  log "Step 4 - Verify: done (images, flake hash, image version)"
}

#
# Step 5 - Publish GitHub release
#

step_publish() {
  local notes="$WORK_DIR/release-notes.md"

  changelog_section "$STAMP_SHA" > "$notes"
  [ -s "$notes" ] || fail "empty release notes: no '## [$V]' section in CHANGELOG.md at $STAMP_SHA"

  # Release candidates are published as prereleases, never latest
  local latest_args=("--latest")
  if [[ "$V" =~ $RC_REGEX ]]; then
    latest_args=("--prerelease")
  fi

  if gh release view "$TAG" --json tagName >/dev/null 2>&1; then
    if [[ "$V" =~ $RC_REGEX ]]; then
      gh release edit "$TAG" --prerelease --draft=false >/dev/null
    else
      gh release edit "$TAG" --latest --draft=false --prerelease=false >/dev/null
    fi
  else
    gh release create "$TAG" --verify-tag "${latest_args[@]}" --title "$TAG" --notes-file "$notes" >/dev/null
  fi

  RELEASE_URL=$(gh release view "$TAG" --json url --jq .url)
  log "Step 5 - Publish: done ($RELEASE_URL)"
}

#
# Step 6 - Open PR to master (never merged by this script)
#

step_pr() {
  local url body="$WORK_DIR/pr-body.md"

  url=$(release_pr_field open url)

  if [ -z "$url" ]; then
    {
      echo "Release [$TAG]($RELEASE_URL). Container images built by [Release run]($RELEASE_RUN_URL) and verified."
      echo
      echo "> [!IMPORTANT]"
      echo "> Merge with a **merge commit** (no squash, no rebase): tag \`$TAG\` must stay reachable from \`$BASE_BRANCH\`."
      echo "> Merging makes the release live for \`install.sh\` users."
      echo
      cat "$WORK_DIR/release-notes.md"
    } > "$body"

    url=$(gh pr create --base "$BASE_BRANCH" --head "$BRANCH" --title "Release $TAG" --body-file "$body")
  fi

  log "Step 6 - PR: done"
  log "Release $TAG ready. Review and merge (merge commit) to go live: $url"
}

#
# Abort
#

abort_release() {
  local pr_url

  [ -z "$(release_pr_field merged url)" ] || fail "release PR for $TAG is merged: cannot abort, fix forward with a new release"

  pr_url=$(release_pr_field open url)
  if [ -n "$pr_url" ]; then
    log "Closing PR $pr_url"
    gh pr close "$pr_url" --comment "Release $TAG aborted" >/dev/null
  fi

  if gh release view "$TAG" --json tagName >/dev/null 2>&1; then
    log "Deleting GitHub release $TAG"
    gh release delete "$TAG" --yes
  fi

  if [ -n "$(remote_tag_commit "$TAG")" ]; then
    log "Deleting remote tag $TAG"
    git push --quiet "$REMOTE" --delete "refs/tags/$TAG"
  fi

  if git rev-parse -q --verify "refs/tags/$TAG" >/dev/null; then
    git tag -d "$TAG" >/dev/null
  fi

  if remote_branch_exists "$BRANCH"; then
    log "Deleting remote branch $BRANCH"
    git push --quiet "$REMOTE" --delete "refs/heads/$BRANCH"
  fi

  if git rev-parse -q --verify "refs/heads/$BRANCH" >/dev/null; then
    if [ "$(git branch --show-current)" = "$BRANCH" ]; then
      git checkout --quiet --detach "$REMOTE/$BASE_BRANCH"
    fi
    git branch --quiet -D "$BRANCH"
  fi

  log "Release $TAG aborted. Container images $V possibly pushed are left as-is."
}

#
# Main
#

main() {
  local mode="release" requested="" remote_tag

  while [ $# -gt 0 ]; do
    case "$1" in
      --abort) mode="abort" ;;
      -h|--help) usage; exit 0 ;;
      -*) fail "unknown option: $1" ;;
      *)
        [ -z "$requested" ] || fail "only one VERSION can be given"
        requested=$1
        ;;
    esac
    shift
  done

  if [ -n "$requested" ] && ! [[ "$requested" =~ $VERSION_REGEX ]]; then
    fail "invalid version '$requested': expected X.Y.Z or X.Y.Z-rc (no 'v' prefix)"
  fi

  if [ "$mode" = "abort" ] && is_dry_run; then
    fail "dry run is not supported with --abort"
  fi

  cd "$(git -C "$(dirname "$0")" rev-parse --show-toplevel)"

  preflight_common

  # Remote is the source of truth: overwrite local tags with remote ones.
  # Local-only tags are kept (tags are not pruned).
  git fetch --quiet --prune --force --tags "$REMOTE"

  V=$(resolve_version "$requested" "$mode")
  [[ "$V" =~ $VERSION_REGEX ]] || fail "invalid version '$V': expected X.Y.Z or X.Y.Z-rc"

  TAG="v$V"
  BRANCH="release-$V"
  STAMP_SUBJECT="chore(release): $TAG"
  WORK_DIR="tmp/release-$V"
  mkdir -p "$WORK_DIR"

  if is_dry_run; then
    log "Release $TAG (branch $BRANCH) - DRY RUN"
  else
    log "Release $TAG (branch $BRANCH)"
  fi

  if [ "$mode" = "abort" ]; then
    abort_release
    return
  fi

  if [ -n "$(release_pr_field merged url)" ]; then
    log "Release PR for $TAG already merged: release is done."
    return
  fi

  remote_tag=$(remote_tag_commit "$TAG")

  if remote_branch_exists "$BRANCH"; then
    log "Resuming release: remote branch $BRANCH exists"
    if [ -n "$remote_tag" ] && [ "$(git rev-parse "$REMOTE/$BRANCH")" != "$remote_tag" ]; then
      fail "remote tag $TAG ($remote_tag) does not point to $REMOTE/$BRANCH HEAD: inconsistent state, abort with: $0 --abort $V"
    fi
  elif [ -n "$remote_tag" ]; then
    fail "remote tag $TAG exists but branch $BRANCH does not: inconsistent state, abort with: $0 --abort $V"
  else
    preflight_fresh
  fi

  step_stamp

  if is_dry_run; then
    log "Dry run: $BRANCH already stamped remotely, nothing to do."
    return
  fi

  step_tag
  step_ci
  step_verify
  step_publish
  step_pr
}

main "$@"
